// replay_rbf.cpp
// Plays saved RBF weights with the greedy policy (no exploration, no learning) and writes
// every simulation step's positions (3 keepers, 2 takers, ball) to a CSV through
// Env::set_trajectory_log. tools/viewer.py turns that CSV into a GIF.
//
//   ./build/replay_rbf <weights.txt> <trajectory.csv> [episodes=1] [first_seed=1000000] [sigma=0.01]
//
// Example:
//   ./build/replay_rbf results/weights/cmp-rbf-final/seed-100010.txt results/replays/rbf.csv 20
//   python3 tools/viewer.py results/replays/rbf.csv --episode 3 --save results/replays/rbf.gif
//
// The number of state variables and centres is read from the weights file, so both
// cmp-rbf-final (13 variables) and cmp-rbf-reduced-final (4 variables) work. sigma is not
// stored in the file; 0.01 is the value used in the final comparison runs (tools/run_experiments.sh cmp_*).
// All three keepers use the loaded weights (Controller::External), as in training.
// Episode i uses env.reset(first_seed + i); the CSV's "episode" column counts from 0.
// ---------------------------------------------------------------------------
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

#include "common.hpp"
#include "learn/q_learning.hpp"
#include "learn/train.hpp"
#include "sim/keepaway_env.hpp"

using namespace keepaway;

int main(int argc, char **argv) {
  if (argc < 3 || argc > 6) {
    std::cerr << "usage: replay_rbf <weights.txt> <trajectory.csv> [episodes=1] "
                 "[first_seed=1000000] [sigma=0.01]\n";
    return 1;
  }
  const std::string weights = argv[1], out = argv[2];
  const int episodes = argc > 3 ? std::stoi(argv[3]) : 1;
  const uint64_t first_seed = argc > 4 ? std::stoull(argv[4]) : 1000000;
  const double sigma = argc > 5 ? std::stod(argv[5]) : 0.01;

  // Header of RadialBasisFunction::save(): "<state variables> <centres> <actions>"
  int sv = 0, centres = 0, actions = 0;
  {
    std::ifstream in(weights);
    if (!(in >> sv >> centres >> actions)) {
      std::cerr << "cannot read the header of " << weights << '\n';
      return 1;
    }
  }
  std::vector<Feature> features;
  if (sv == kNumFeatures) {
    features = kFullFeatures;
  } else if (sv == static_cast<int>(kReducedFeatures.size())) {
    features = kReducedFeatures;
  } else {
    std::cerr << "weights have " << sv << " state variables; expected " << kNumFeatures << " or "
              << kReducedFeatures.size() << '\n';
    return 1;
  }

  Config cfg{.keepers = {Controller::External, Controller::External, Controller::External}};
  Config_RBF cfg_rbf{.num_of_state_variables = sv,
                     .num_of_tiles = centres,
                     .num_of_actions = actions,
                     .standard_deviation = sigma,
                     .alpha = 0.0};
  RadialBasisFunction q(cfg_rbf);
  q.load(weights);

  const auto parent = std::filesystem::path(out).parent_path();
  if (!parent.empty()) std::filesystem::create_directories(parent);

  Env env(cfg);
  env.set_trajectory_log(out);
  const std::vector<Episode> eps = evaluate_policy(q, env, cfg, features, episodes, first_seed);
  env.set_trajectory_log("");

  double total = 0;
  std::cout << "episode,seed,seconds,end\n";
  for (int i = 0; i < episodes; ++i) {
    total += eps[i].seconds;
    std::cout << i << ',' << first_seed + i << ',' << eps[i].seconds << ',' << reason_name(eps[i].reason)
              << '\n';
  }
  std::cout << "# " << episodes << " episodes, mean " << total / episodes << " s, positions in " << out
            << '\n';
  return 0;
}
